const XS=[1,2,3,4,5,6];
const YS=[1.6,3.1,3.4,5.2,7.6,6.4];
const X0=60,Y0=30,W=400,H=460,S=40;
function px(x){return X0+x*S;}
function py(y){return Y0+H-(y+1.5)*S;}
function sg(v){return (v>=0?'+':'')+sdk.format(v,2);}
export function evaluate({inputs}){
 const m=inputs.slope,b=inputs.intercept;
 const f=inputs.focus;
 const sel=f==='none'?-1:(parseInt(f.slice(1),10)-1);
 const clip={x:X0,y:Y0,w:W,h:H};
 const o=[];
 o.push(sdk.line('xaxis',px(0),py(0),px(10),py(0),{role:'neutral'}));
 o.push(sdk.line('yaxis',px(0),Y0,px(0),Y0+H,{role:'neutral'}));
 o.push(sdk.text('xl',px(10)-12,py(0)+20,'x'));
 o.push(sdk.text('yl',px(0)+12,Y0+14,'y'));
 o.push(sdk.line('xt5',px(5),py(0)-4,px(5),py(0)+4,{role:'neutral'}));
 o.push(sdk.line('xt5b',px(5),Y0+H-4,px(5),Y0+H,{role:'neutral'}));
 o.push(sdk.text('x5',px(5)-4,Y0+H+18,'5'));
 o.push(sdk.line('yt5',px(0)-4,py(5),px(0)+4,py(5),{role:'neutral'}));
 o.push(sdk.text('y5',px(0)-18,py(5)+4,'5'));
 o.push({kind:'polyline',id:'fit',points:[[px(0),py(b)],[px(10),py(b+10*m)]],clip:clip,role:'prediction'});
 const e=[],e2=[];let sse=0;
 for(let i=0;i<6;i++){const p=m*XS[i]+b;const r=YS[i]-p;e.push(r);e2.push(r*r);sse+=r*r;}
 const mse=sse/6;
 for(let i=0;i<6;i++){
  const hi=i===sel;const dim=sel>=0&&!hi;
  const xp=px(XS[i]),yp=py(YS[i]),yl=py(m*XS[i]+b);const d=yl-yp;const s=Math.abs(d)*0.5;const ys=yp+Math.sign(d)*s;
  o.push({kind:'polyline',id:'sq'+i,points:[[xp,yp],[xp+s,yp],[xp+s,ys],[xp,ys],[xp,yp]],clip:clip,role:hi?'warning':'neutral',opacity:hi?0.9:(dim?0.15:0.4)});
  o.push({kind:'polyline',id:'err'+i,points:[[xp,yp],[xp,yl]],clip:clip,role:'warning',opacity:dim?0.3:1});
  o.push(sdk.circle('pt'+i,xp,yp,10,{role:'observed'}));
  o.push(sdk.text('pl'+i,xp-16,yp-8,String(i+1)));
 }
 const sb=b>=0?'+ '+sdk.format(b,2):'- '+sdk.format(-b,2);
 o.push(sdk.math('eq',520,50,'\\hat{y} = '+sdk.format(m,2)+'x '+sb));
 o.push(sdk.text('hdr',520,95,'Error e, square e², share of total'));
 for(let i=0;i<6;i++){
  const hi=i===sel;const dim=sel>=0&&!hi;
  const share=sse>1e-12?e2[i]/sse:0;
  const y=125+i*44;
  o.push(sdk.text('row'+i,520,y,'Point '+(i+1)+':  e = '+sg(e[i])+',  e² = '+sdk.format(e2[i],2)+'  ('+sdk.format(share*100,1)+'%)',{role:hi?'warning':'neutral',opacity:dim?0.5:1}));
  o.push(sdk.box('bar'+i,520,y+8,Math.max(2,share*380),14,{role:hi?'warning':'prediction',opacity:dim?0.35:1}));
 }
 o.push(sdk.math('mf',520,410,'\\text{MSE} = \\frac{1}{6}\\sum_{i=1}^{6} e_i^2'));
 o.push(sdk.text('mn',520,465,'= ('+e2.map(v=>sdk.format(v,2)).join(' + ')+') / 6'));
 o.push(sdk.text('mv',520,495,'= '+sdk.format(mse,3),{role:'output'}));
 const fs=sel>=0&&sse>1e-12?100*e2[sel]/sse:0;
 return {frame:{width:960,height:540,objects:o,readouts:[{id:'mse',value:mse},{id:'sse',value:sse},{id:'focus_share',value:fs}]},quantities:{mse:mse,sse:sse,focus_share:fs}};
}

